  "site:aetna.com find a doctor"
];

for (const q of searches) {
  const url = `https://www.google.com/search?q=${encodeURIComponent(q)}`;
  await tool.navigate({ tabId: 787783793, url });
  await tool.wait_for({ tabId: 787783793, condition: "selector_visible", value: "#search", timeout_ms: 5000 });
  const links = await browserjs(787783793, () => {
    return Array.from(document.querySelectorAll("#search a"))
      .map(a => ({ href: a.href, text: a.innerText?.trim() }))
      .filter(l => l.href && !l.href.includes("google.com"))
      .slice(0, 3);
  });
  console.log(`Query: "${q}" ->`, JSON.stringify(links));
}
","title":"Find official insurer overview and directory URLs via Google","cwd":null}
